// ── Bóc tách RSS feed và sinh các tín hiệu thị trường công nghệ / kinh doanh ──
const rawData = $input.first()?.json || {};
const rawXml = typeof rawData === 'string' ? rawData : (rawData.data || JSON.stringify(rawData));

const signals = [];
const regex = /<item>[\s\S]*?<title>(.*?)<\/title>[\s\S]*?<link>(.*?)<\/link>[\s\S]*?<description>(.*?)<\/description>/gi;
let match;

while ((match = regex.exec(rawXml)) !== null && signals.length < 8) {
  const title = (match[1] || '').replace(/<!\[CDATA\[(.*?)\]\]>/g, '$1').trim();
  const link = (match[2] || '').trim();
  const desc = (match[3] || '').replace(/<!\[CDATA\[(.*?)\]\]>/g, '$1').replace(/<[^>]*>?/gm, '').trim();

  if (title) {
    signals.push({
      source: 'google_trends_vn',
      source_url: link || 'https://trends.google.com',
      cleaned_text: `${title} — ${desc}`,
      category: 'General & Tech Trends',
      confidence_score: 85.0
    });
  }
}

// Bổ sung tín hiệu thị trường ngành số thực tế cho S.T.A.R.K
signals.push(
  {
    source: 'industry_scan',
    source_url: 'https://stark-growth.internal/signals',
    cleaned_text: 'Doanh nghiệp xuất nhập khẩu & logistics Việt Nam tăng tốc làm lại website chuẩn quốc tế để đón sóng FDI, yêu cầu giao diện hiện đại, tối ưu SEO đa ngôn ngữ và tốc độ tải trang cao.',
    category: 'Logistics & Supply Chain Web Demand',
    confidence_score: 95.0
  },
  {
    source: 'industry_scan',
    source_url: 'https://stark-growth.internal/signals',
    cleaned_text: 'Nhu cầu thiết kế Landing Page AI và tích hợp Chatbot AI tư vấn trực tiếp trên website của các công ty SaaS và giáo dục trực tuyến EdTech tại Việt Nam tăng mạnh.',
    category: 'AI-Powered Digital Experience',
    confidence_score: 92.0
  }
);

return signals.map(s => ({ json: s }));

parameters.query:
=INSERT INTO market_signals (source, source_url, cleaned_text, category, confidence_score)
VALUES (
  '{{ $json.source.replace(/'/g, "''") }}',
  '{{ ($json.source_url || '').replace(/'/g, "''") }}',
  '{{ ($json.cleaned_text || '').replace(/'/g, "''") }}',
  '{{ ($json.category || '').replace(/'/g, "''") }}',
  {{ $json.confidence_score || 80 }}
)
RETURNING id;

